package com.careerpilot.modules.assessment.entity;
import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="assessment_answers") @Getter @Setter @NoArgsConstructor
public class AssessmentAnswer{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="attempt_id")private AssessmentAttempt attempt;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="question_id")private AssessmentQuestion question;@Column(name="selected_option_key",length=10)private String selectedOptionKey;@Column(name="text_answer",length=2000)private String textAnswer;@Column(name="is_correct")private Boolean correct;@Column(name="awarded_points",nullable=false,precision=6,scale=2)private BigDecimal awardedPoints;@Column(name="created_at",nullable=false)private Instant createdAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=Instant.now();}}
